    "mail.style_name_ph": "p. ex. Formel",
    "mail.style_text_suggest": "Répondre de façon formelle, factuelle et en cinq phrases au maximum.\nCommencer par confirmer brièvement la demande.\nNe s'engager sur aucun prix, remise ou délai de livraison.\nConclure par :\nCordialement\n<Nom>\n<Service>",
    "mail.style_text": "Style et signature",
    "mail.style_is_default": "Utiliser par défaut quand rien n'est choisi",
    "mail.style_default": "par défaut",
